using System;using System.IO;using System.Linq;using System.Collections;using System.Reflection;using UnityEngine;using UnityEditor;using Assets.Script.DynamicCards;using Assets.Script.DynamicCards.Editor;
public static class MotionWork {
const string W="C:/UnityProjects/LegacyGwent/work/DynamicCards/MotionIntegrity/";
public static void Run(){try{var type=typeof(DynamicCardContentImporter);var conversionType=type.GetNestedType("Conversion",BindingFlags.NonPublic);var apply=type.GetMethod("ApplyTextureAssignments",BindingFlags.NonPublic|BindingFlags.Static);int checkedBindings=0,checkedMaterials=0;foreach(var path in Directory.GetFiles(DynamicCardLibrary.ContentRoot,"conversion.json",SearchOption.AllDirectories)){var record=JsonUtility.FromJson(File.ReadAllText(path),conversionType);var assignments=((IEnumerable)conversionType.GetField("textureAssignments").GetValue(record)).Cast<object>().ToArray();var materials=((IEnumerable)conversionType.GetField("materials").GetValue(record)).Cast<object>();foreach(var info in materials){var name=(string)info.GetType().GetField("originalName").GetValue(info);var matching=assignments.Where(a=>(string)a.GetType().GetField("material").GetValue(a)==name).ToArray();if(matching.Length==0)continue;var asset=(string)info.GetType().GetField("asset").GetValue(info);var original=AssetDatabase.LoadAssetAtPath<Material>(asset);if(original==null)continue;var clone=new Material(original);try{foreach(var a in matching)foreach(var property in (string[])a.GetType().GetField("properties").GetValue(a))if(clone.HasProperty(property))clone.SetTexture(property,null);apply.Invoke(null,new[]{clone,(object)name,record});foreach(var a in matching)foreach(var property in (string[])a.GetType().GetField("properties").GetValue(a)){if(!clone.HasProperty(property))continue;var explicitPath=(string)a.GetType().GetField("texture").GetValue(a);var expected=string.IsNullOrEmpty(explicitPath)?(string)conversionType.GetField("atlas").GetValue(record):explicitPath;if(AssetDatabase.GetAssetPath(clone.GetTexture(property))!=expected)throw new Exception(asset+" "+property+" restore failed");checkedBindings++;}checkedMaterials++;}finally{UnityEngine.Object.DestroyImmediate(clone);}}}File.WriteAllText(W+"final-import-replay.txt","OK materials="+checkedMaterials+" bindings="+checkedBindings+"; cleared cloned material bindings then restored via production importer; original assets unchanged");}catch(Exception e){File.WriteAllText(W+"final-import-replay.txt",e.ToString());}}
}